18	// Forward method for converting the input spherical harmonics
19	// coefficients of each Gaussian to a simple RGB color.
20	__device__ glm::vec3 computeColorFromSH(int idx, int deg, int max_coeffs, const glm::vec3* means, glm::vec3 campos, const float* shs, bool* clamped)
21	{
22		// The implementation is loosely based on code for 
23		// "Differentiable Point-Based Radiance Fields for 
24		// Efficient View Synthesis" by Zhang et al. (2022)
25		glm::vec3 pos = means[idx];
26		glm::vec3 dir = pos - campos;
27		dir = dir / glm::length(dir);
28	
29		glm::vec3* sh = ((glm::vec3*)shs) + idx * max_coeffs;
30		glm::vec3 result = SH_C0 * sh[0];
31	
32		if (deg > 0)
33		{
34			float x = dir.x;
35			float y = dir.y;
36			float z = dir.z;
37			result = result - SH_C1 * y * sh[1] + SH_C1 * z * sh[2] - SH_C1 * x * sh[3];
38	
39			if (deg > 1)
40			{
41				float xx = x * x, yy = y * y, zz = z * z;
42				float xy = x * y, yz = y * z, xz = x * z;
43				result = result +
44					SH_C2[0] * xy * sh[4] +
45					SH_C2[1] * yz * sh[5] +
46					SH_C2[2] * (2.0f * zz - xx - yy) * sh[6] +
47					SH_C2[3] * xz * sh[7] +
48					SH_C2[4] * (xx - yy) * sh[8];
49	
50				if (deg > 2)
51				{
52					result = result +
53						SH_C3[0] * y * (3.0f * xx - yy) * sh[9] +
54						SH_C3[1] * xy * z * sh[10] +
55						SH_C3[2] * y * (4.0f * zz - xx - yy) * sh[11] +
56						SH_C3[3] * z * (2.0f * zz - 3.0f * xx - 3.0f * yy) * sh[12] +
57						SH_C3[4] * x * (4.0f * zz - xx - yy) * sh[13] +
58						SH_C3[5] * z * (xx - yy) * sh[14] +
59						SH_C3[6] * x * (xx - 3.0f * yy) * sh[15];
60				}
61			}
62		}
63		result += 0.5f;
64	
65		// RGB colors are clamped to positive values. If values are
66		// clamped, we need to keep track of this for the backward pass.
67		clamped[3 * idx + 0] = (result.x < 0);
68		clamped[3 * idx + 1] = (result.y < 0);
69		clamped[3 * idx + 2] = (result.z < 0);
70		return glm::max(result, 0.0f);
71	}
72	
73	__device__ glm::vec3 computeColorFromSH_4D(int idx, int deg, int deg_t, int max_coeffs, const glm::vec3* means,
74			 glm::vec3 campos, const float* shs, bool* clamped, const float* ts, const float timestamp, const float time_duration)
75	{
76		// The implementation is loosely based on code for
77		// "Differentiable Point-Based Radiance Fields for
78		// Efficient View Synthesis" by Zhang et al. (2022)
79		glm::vec3 pos = means[idx];
80		glm::vec3 dir = pos - campos;
81		dir = dir / glm::length(dir);
82	
83		const float dir_t = ts[idx]-timestamp;
84	
85		glm::vec3* sh = ((glm::vec3*)shs) + idx * max_coeffs;
86	
87		float l0m0=SH_C0;
88		glm::vec3 result = l0m0 * sh[0];
89	
90		if (deg > 0)
91		{
92			float x = dir.x;
93			float y = dir.y;
94			float z = dir.z;
95	
96			float l1m1 = -1 * SH_C1 * y;
97			float l1m0 = SH_C1 * z;
98			float l1p1 = -1 * SH_C1 * x;
99	
100			result += 
101				l1m1 * sh[1] +
102				l1m0 * sh[2] +
103				l1p1 * sh[3];
104	
105			if (deg > 1)
106			{
107				float xx = x * x, yy = y * y, zz = z * z;
108				float xy = x * y, yz = y * z, xz = x * z;
109	
110				float l2m2 = SH_C2[0] * xy;
111	            float l2m1 = SH_C2[1] * yz;
112	            float l2m0 = SH_C2[2] * (2.0 * zz - xx - yy);
113	            float l2p1 = SH_C2[3] * xz;
114	            float l2p2 = SH_C2[4] * (xx - yy);
115	
116				result +=
117	                l2m2 * sh[4] +
118	                l2m1 * sh[5] +
119	                l2m0 * sh[6] +
120	                l2p1 * sh[7] +
121	                l2p2 * sh[8];
122	
123				if (deg > 2)
124				{
125					float l3m3 = SH_C3[0] * y * (3 * xx - yy);
126	                float l3m2 = SH_C3[1] * xy * z;
127	                float l3m1 = SH_C3[2] * y * (4 * zz - xx - yy);
128	                float l3m0 = SH_C3[3] * z * (2 * zz - 3 * xx - 3 * yy);
129	                float l3p1 = SH_C3[4] * x * (4 * zz - xx - yy);
130	                float l3p2 = SH_C3[5] * z * (xx - yy);
131	                float l3p3 = SH_C3[6] * x * (xx - 3 * yy);
132	
133					result +=
134						l3m3 * sh[9] +
135						l3m2 * sh[10] +
136						l3m1 * sh[11] +
137						l3m0 * sh[12] +
138						l3p1 * sh[13] +
139						l3p2 * sh[14] +
140						l3p3 * sh[15];
141	
142					if (deg_t > 0){
143						float t1 = cos(2 * MY_PI * dir_t / time_duration);
144	
145						result += t1 * (l0m0 * sh[16] +
146							l1m1 * sh[17] +
147							l1m0 * sh[18] +
148							l1p1 * sh[19] + 
149							l2m2 * sh[20] +
150							l2m1 * sh[21] +
151							l2m0 * sh[22] +
152							l2p1 * sh[23] +
153							l2p2 * sh[24] + 
154							l3m3 * sh[25] +
155							l3m2 * sh[26] +
156							l3m1 * sh[27] +
157							l3m0 * sh[28] +
158							l3p1 * sh[29] +
159							l3p2 * sh[30] +
160							l3p3 * sh[31]);
161	
162						if (deg_t > 1){
163							float t2 = cos(2 * MY_PI * dir_t * 2 / time_duration);
164	
165							result += t2 * (l0m0 * sh[32] +
166								l1m1 * sh[33] +
167								l1m0 * sh[34] +
168								l1p1 * sh[35] + 
169								l2m2 * sh[36] +
170								l2m1 * sh[37] +
171								l2m0 * sh[38] +
172								l2p1 * sh[39] +
173								l2p2 * sh[40] + 
174								l3m3 * sh[41] +
175								l3m2 * sh[42] +
176								l3m1 * sh[43] +
177								l3m0 * sh[44] +
178								l3p1 * sh[45] +
179								l3p2 * sh[46] +
180								l3p3 * sh[47]);
181						}
182	
183					}
184				}
185			}
186		}
187		result += 0.5f;
188	
189		// RGB colors are clamped to positive values. If values are
190		// clamped, we need to keep track of this for the backward pass.
191		clamped[3 * idx + 0] = (result.x < 0);
192		clamped[3 * idx + 1] = (result.y < 0);
193		clamped[3 * idx + 2] = (result.z < 0);
194		return glm::max(result, 0.0f);
195	}
