197	// Forward version of 2D covariance matrix computation
198	__device__ float3 computeCov2D(const float3& mean, float focal_x, float focal_y, float tan_fovx, float tan_fovy, const float* cov3D, const float* viewmatrix)
199	{
200		// The following models the steps outlined by equations 29
201		// and 31 in "EWA Splatting" (Zwicker et al., 2002). 
202		// Additionally considers aspect / scaling of viewport.
203		// Transposes used to account for row-/column-major conventions.
204		float3 t = transformPoint4x3(mean, viewmatrix);
205	
206		const float limx = 1.3f * tan_fovx;
207		const float limy = 1.3f * tan_fovy;
208		const float txtz = t.x / t.z;
209		const float tytz = t.y / t.z;
210		t.x = min(limx, max(-limx, txtz)) * t.z;
211		t.y = min(limy, max(-limy, tytz)) * t.z;
212	
213		glm::mat3 J = glm::mat3(
214			focal_x / t.z, 0.0f, -(focal_x * t.x) / (t.z * t.z),
215			0.0f, focal_y / t.z, -(focal_y * t.y) / (t.z * t.z),
216			0, 0, 0);
217	
218		glm::mat3 W = glm::mat3(
219			viewmatrix[0], viewmatrix[4], viewmatrix[8],
220			viewmatrix[1], viewmatrix[5], viewmatrix[9],
221			viewmatrix[2], viewmatrix[6], viewmatrix[10]);
222	
223		glm::mat3 T = W * J;
224	
225		glm::mat3 Vrk = glm::mat3(
226			cov3D[0], cov3D[1], cov3D[2],
227			cov3D[1], cov3D[3], cov3D[4],
228			cov3D[2], cov3D[4], cov3D[5]);
229	
230		glm::mat3 cov = glm::transpose(T) * glm::transpose(Vrk) * T;
231	
232		// Apply low-pass filter: every Gaussian should be at least
233		// one pixel wide/high. Discard 3rd row and column.
234		cov[0][0] += 0.3f;
235		cov[1][1] += 0.3f;
236		return { float(cov[0][0]), float(cov[0][1]), float(cov[1][1]) };
237	}
