239	// Forward method for converting scale and rotation properties of each
240	// Gaussian to a 3D covariance matrix in world space. Also takes care
241	// of quaternion normalization.
242	__device__ void computeCov3D(const glm::vec3 scale, float mod, const glm::vec4 rot, float* cov3D)
243	{
244		// Create scaling matrix
245		glm::mat3 S = glm::mat3(1.0f);
246		S[0][0] = mod * scale.x;
247		S[1][1] = mod * scale.y;
248		S[2][2] = mod * scale.z;
249	
250		// Normalize quaternion to get valid rotation
251		glm::vec4 q = rot;// / glm::length(rot);
252		float r = q.x;
253		float x = q.y;
254		float y = q.z;
255		float z = q.w;
256	
257		// Compute rotation matrix from quaternion
258		glm::mat3 R = glm::mat3(
259			1.f - 2.f * (y * y + z * z), 2.f * (x * y - r * z), 2.f * (x * z + r * y),
260			2.f * (x * y + r * z), 1.f - 2.f * (x * x + z * z), 2.f * (y * z - r * x),
261			2.f * (x * z - r * y), 2.f * (y * z + r * x), 1.f - 2.f * (x * x + y * y)
262		);
263	
264		glm::mat3 M = S * R;
265	
266		// Compute 3D world covariance matrix Sigma
267		glm::mat3 Sigma = glm::transpose(M) * M;
268	
269		// Covariance is symmetric, only store upper right
270		cov3D[0] = Sigma[0][0];
271		cov3D[1] = Sigma[0][1];
272		cov3D[2] = Sigma[0][2];
273		cov3D[3] = Sigma[1][1];
274		cov3D[4] = Sigma[1][2];
275		cov3D[5] = Sigma[2][2];
276	}
