278	
279	__device__ void computeCov3D_conditional(const glm::vec3 scale, const float scale_t, float mod,
280			const glm::vec4 rot, const glm::vec4 rot_r, float* cov3D, float3& p_orig,
281			float t, const float timestamp, int idx, bool& mask, float& opacity)
282	{
283		// Create scaling matrix
284		float dt=timestamp-t;
285		glm::mat4 S = glm::mat4(1.0f);
286		S[0][0] = mod * scale.x;
287		S[1][1] = mod * scale.y;
288		S[2][2] = mod * scale.z;
289		S[3][3] = mod * scale_t;
290	
291		float a = rot.x;
292		float b = rot.y;
293		float c = rot.z;
294		float d = rot.w;
295	
296		float p = rot_r.x;
297		float q = rot_r.y;
298		float r = rot_r.z;
299		float s = rot_r.w;
300	
301		// glm::mat4 M_l = glm::mat4(
302		// 	a, -b, -c, -d,
303		// 	b, a,-d, c,
304		// 	c, d, a,-b,
305		// 	d,-c, b, a
306		// );
307	
308		// glm::mat4 M_r = glm::mat4(
309		// 	p, q, r, s,
310		// 	-q, p,-s, r,
311		// 	-r, s, p,-q,
312		// 	-s,-r, q, p
313		// );
314		
315		glm::mat4 M_l = glm::mat4(
316			 a,  b, -c,  d,
317			-b,  a,  d,  c,
318			 c, -d,  a,  b,
319			-d, -c, -b,  a
320		);
321	
322		glm::mat4 M_r = glm::mat4(
323			p,  q, -r, -s,
324			-q, p,  s, -r,
325			r, -s,  p, -q,
326			s,  r,  q,  p
327		);
328		// glm stores in column major
329		glm::mat4 R = M_r * M_l;
330		glm::mat4 M = S * R;
331		glm::mat4 Sigma = glm::transpose(M) * M;
332		float cov_t = Sigma[3][3];
333		float marginal_t = __expf(-0.5*dt*dt/cov_t);
334		mask = marginal_t > 0.05;
335		if (!mask) return;
336		opacity*=marginal_t;;
337		glm::mat3 cov11 = glm::mat3(Sigma);
338		glm::vec3 cov12 = glm::vec3(Sigma[0][3],Sigma[1][3],Sigma[2][3]);
339		glm::mat3 cov3D_condition = cov11 - glm::outerProduct(cov12, cov12) / cov_t;
340	
341		// Covariance is symmetric, only store upper right
342		cov3D[0] = cov3D_condition[0][0];
343		cov3D[1] = cov3D_condition[0][1];
344		cov3D[2] = cov3D_condition[0][2];
345		cov3D[3] = cov3D_condition[1][1];
346		cov3D[4] = cov3D_condition[1][2];
347		cov3D[5] = cov3D_condition[2][2];
348	    glm::vec3 delta_mean = cov12 / cov_t * dt;
349		p_orig.x+=delta_mean.x;
350		p_orig.y+=delta_mean.y;
351		p_orig.z+=delta_mean.z;
352	}
