354	// Perform initial steps for each Gaussian prior to rasterization.
355	template<int C>
356	__global__ void preprocessCUDA(int P, int D, int D_t, int M,
357		const float* orig_points,
358		float* out_means3D,
359		const float* ts,
360		const glm::vec3* scales,
361		const float* scales_t,
362		const float scale_modifier,
363		const glm::vec4* rotations,
364		const glm::vec4* rotations_r,
365		const float* opacities,
366		const float* shs,
367		bool* clamped,
368		const float* cov3D_precomp,
369		const float* colors_precomp,
370		const float* viewmatrix,
371		const float* projmatrix,
372		const glm::vec3* cam_pos,
373		const float timestamp,
374		const float time_duration,
375		const bool rot_4d, const int gaussian_dim, const bool force_sh_3d,
376		const int W, int H,
377		const float tan_fovx, float tan_fovy,
378		const float focal_x, float focal_y,
379		int* radii,
380		float2* points_xy_image,
381		float* depths,
382		float* cov3Ds,
383		float* rgb,
384		float4* conic_opacity,
385		const dim3 grid,
386		uint32_t* tiles_touched,
387		bool prefiltered)
388	{
389		auto idx = cg::this_grid().thread_rank();
390		if (idx >= P)
391			return;
392	
393		// Initialize radius and touched tiles to 0. If this isn't changed,
394		// this Gaussian will not be processed further.
395		radii[idx] = 0;
396		tiles_touched[idx] = 0;
397	
398		// // Perform near culling, quit if outside.
399		// float3 p_view;
400		// if (!in_frustum(idx, orig_points, viewmatrix, projmatrix, prefiltered, p_view))
401		// 	return;
402	
403		// Transform point by projecting
404		float3 p_orig = { orig_points[3 * idx], orig_points[3 * idx + 1], orig_points[3 * idx + 2] };
405		float opacity = opacities[idx];
406	
407		// If 3D covariance matrix is precomputed, use it, otherwise compute
408		// from scaling and rotation parameters.
409		const float* cov3D;
410		if (cov3D_precomp != nullptr)
411		{
412			cov3D = cov3D_precomp + idx * 6;
413		}
414		else if (rot_4d) // gaussian_dim == 4 && rot_4d
415		{
416			bool time_mask=true;
417			computeCov3D_conditional(scales[idx], scales_t[idx], scale_modifier,
418				rotations[idx], rotations_r[idx], cov3Ds + idx * 6, p_orig, ts[idx], timestamp, idx, time_mask, opacity);
419			if (!time_mask) return;
420			cov3D = cov3Ds + idx * 6;
421			out_means3D[idx*3+0]=p_orig.x;
422			out_means3D[idx*3+1]=p_orig.y;
423			out_means3D[idx*3+2]=p_orig.z;
424		}
425		else
426		{
427			computeCov3D(scales[idx], scale_modifier, rotations[idx], cov3Ds + idx * 6);
428			cov3D = cov3Ds + idx * 6;
429			if (gaussian_dim == 4){  // no rot_4d
430	            float dt = ts[idx]-timestamp;
431	            float sigma = scales_t[idx] * scale_modifier;
432			    float marginal_t = __expf(-0.5*dt*dt/sigma);
433			    if (marginal_t <= 0.05) return;
434			    opacity *= marginal_t;
435			}
436		}
437	
438		// Perform near culling, quit if outside.
439		float3 p_view;
440		if (!in_frustum(p_orig, viewmatrix, projmatrix, prefiltered, p_view))
441			return;
442	
443		// Transform point by projecting
444		float4 p_hom = transformPoint4x4(p_orig, projmatrix);
445		float p_w = 1.0f / (p_hom.w + 0.0000001f);
446		float3 p_proj = { p_hom.x * p_w, p_hom.y * p_w, p_hom.z * p_w };
447	
448		// Compute 2D screen-space covariance matrix
449		float3 cov = computeCov2D(p_orig, focal_x, focal_y, tan_fovx, tan_fovy, cov3D, viewmatrix);
450	
451		// Invert covariance (EWA algorithm)
452		float det = (cov.x * cov.z - cov.y * cov.y);
453		if (det == 0.0f)
454			return;
455		float det_inv = 1.f / det;
456		float3 conic = { cov.z * det_inv, -cov.y * det_inv, cov.x * det_inv };
457	
458		// Compute extent in screen space (by finding eigenvalues of
459		// 2D covariance matrix). Use extent to compute a bounding rectangle
460		// of screen-space tiles that this Gaussian overlaps with. Quit if
461		// rectangle covers 0 tiles. 
462		float mid = 0.5f * (cov.x + cov.z);
463		float lambda1 = mid + sqrt(max(0.1f, mid * mid - det));
464		float lambda2 = mid - sqrt(max(0.1f, mid * mid - det));
465		float my_radius = ceil(3.f * sqrt(max(lambda1, lambda2)));
466		float2 point_image = { ndc2Pix(p_proj.x, W), ndc2Pix(p_proj.y, H) };
467		uint2 rect_min, rect_max;
468		getRect(point_image, my_radius, rect_min, rect_max, grid);
469		if ((rect_max.x - rect_min.x) * (rect_max.y - rect_min.y) == 0 || ((int)my_radius <= 0.4))
470			return;
471	
472		// If colors have been precomputed, use them, otherwise convert
473		// spherical harmonics coefficients to RGB color.
474		if (colors_precomp == nullptr)
475		{
476			glm::vec3 result;
477			if (gaussian_dim == 3 || force_sh_3d){
478				result = computeColorFromSH(idx, D, M, (glm::vec3*)orig_points, *cam_pos, shs, clamped);
479			}else{
480				result = computeColorFromSH_4D(idx, D, D_t, M, (glm::vec3*)orig_points, *cam_pos, shs, clamped, ts, timestamp, time_duration);
481			}
482			rgb[idx * C + 0] = result.x;
483			rgb[idx * C + 1] = result.y;
484			rgb[idx * C + 2] = result.z;
485		}
486	
487		// Store some useful helper data for the next steps.
488		depths[idx] = p_view.z;
489		radii[idx] = my_radius;
490		points_xy_image[idx] = point_image;
491		// Inverse 2D covariance and opacity neatly pack into one float4
492		conic_opacity[idx] = { conic.x, conic.y, conic.z, opacity };
493		tiles_touched[idx] = (rect_max.y - rect_min.y) * (rect_max.x - rect_min.x);
494	}
