496	// Main rasterization method. Collaboratively works on one tile per
497	// block, each thread treats one pixel. Alternates between fetching 
498	// and rasterizing data.
499	template <uint32_t CHANNELS>
500	__global__ void __launch_bounds__(BLOCK_X * BLOCK_Y)
501	renderCUDA(
502		const uint2* __restrict__ ranges,
503		const uint32_t* __restrict__ point_list,
504		int W, int H,
505		const float2* __restrict__ points_xy_image,
506		const float* __restrict__ features,
507		const float* __restrict__ flows,
508		const float* __restrict__ depths,
509		const float4* __restrict__ conic_opacity,
510		float* __restrict__ final_T,
511		uint32_t* __restrict__ n_contrib,
512		const float* __restrict__ bg_color,
513		float* __restrict__ out_color,
514		float* __restrict__ out_flow,
515		float* __restrict__ out_depth)
516	{
517		// Identify current tile and associated min/max pixel range.
518		auto block = cg::this_thread_block();
519		uint32_t horizontal_blocks = (W + BLOCK_X - 1) / BLOCK_X;
520		uint2 pix_min = { block.group_index().x * BLOCK_X, block.group_index().y * BLOCK_Y };
521		uint2 pix_max = { min(pix_min.x + BLOCK_X, W), min(pix_min.y + BLOCK_Y , H) };
522		uint2 pix = { pix_min.x + block.thread_index().x, pix_min.y + block.thread_index().y };
523		uint32_t pix_id = W * pix.y + pix.x;
524		float2 pixf = { (float)pix.x, (float)pix.y };
525	
526		// Check if this thread is associated with a valid pixel or outside.
527		bool inside = pix.x < W&& pix.y < H;
528		// Done threads can help with fetching, but don't rasterize
529		bool done = !inside;
530	
531		// Load start/end range of IDs to process in bit sorted list.
532		uint2 range = ranges[block.group_index().y * horizontal_blocks + block.group_index().x];
533		const int rounds = ((range.y - range.x + BLOCK_SIZE - 1) / BLOCK_SIZE);
534		int toDo = range.y - range.x;
535	
536		// Allocate storage for batches of collectively fetched data.
537		__shared__ int collected_id[BLOCK_SIZE];
538		__shared__ float2 collected_xy[BLOCK_SIZE];
539		__shared__ float4 collected_conic_opacity[BLOCK_SIZE];
540	
541		// Initialize helper variables
542		float T = 1.0f;
543		uint32_t contributor = 0;
544		uint32_t last_contributor = 0;
545		float C[CHANNELS] = { 0 };
546		float Flow[2] = { 0 };
547		float D = { 0 };
548	
549		// Iterate over batches until all done or range is complete
550		for (int i = 0; i < rounds; i++, toDo -= BLOCK_SIZE)
551		{
552			// End if entire block votes that it is done rasterizing
553			int num_done = __syncthreads_count(done);
554			if (num_done == BLOCK_SIZE)
555				break;
556	
557			// Collectively fetch per-Gaussian data from global to shared
558			int progress = i * BLOCK_SIZE + block.thread_rank();
559			if (range.x + progress < range.y)
560			{
561				int coll_id = point_list[range.x + progress];
562				collected_id[block.thread_rank()] = coll_id;
563				collected_xy[block.thread_rank()] = points_xy_image[coll_id];
564				collected_conic_opacity[block.thread_rank()] = conic_opacity[coll_id];
565			}
566			block.sync();
567	
568			// Iterate over current batch
569			for (int j = 0; !done && j < min(BLOCK_SIZE, toDo); j++)
570			{
571				// Keep track of current position in range
572				contributor++;
573	
574				// Resample using conic matrix (cf. "Surface 
575				// Splatting" by Zwicker et al., 2001)
576				float2 xy = collected_xy[j];
577				float2 d = { xy.x - pixf.x, xy.y - pixf.y };
578				float4 con_o = collected_conic_opacity[j];
579				float power = -0.5f * (con_o.x * d.x * d.x + con_o.z * d.y * d.y) - con_o.y * d.x * d.y;
580				if (power > 0.0f)
581					continue;
582	
583				// Eq. (2) from 3D Gaussian splatting paper.
584				// Obtain alpha by multiplying with Gaussian opacity
585				// and its exponential falloff from mean.
586				// Avoid numerical instabilities (see paper appendix). 
587				float alpha = min(0.99f, con_o.w * exp(power));
588				if (alpha < 1.0f / 255.0f)
589					continue;
590				float test_T = T * (1 - alpha);
591				if (test_T < 0.0001f)
592				{
593					done = true;
594					continue;
595				}
596	
597				// Eq. (3) from 3D Gaussian splatting paper.
598				for (int ch = 0; ch < CHANNELS; ch++)
599					C[ch] += features[collected_id[j] * CHANNELS + ch] * alpha * T;
600				for (int ch = 0; ch < 2; ch++)
601					Flow[ch] += flows[collected_id[j] * 2 + ch] * alpha * T;
602				D += depths[collected_id[j]] * alpha * T;
603	
604				T = test_T;
605	
606				// Keep track of last range entry to update this
607				// pixel.
608				last_contributor = contributor;
609			}
610		}
611	
612		// All threads that treat valid pixel write out their final
613		// rendering data to the frame and auxiliary buffers.
614		if (inside)
615		{
616			final_T[pix_id] = T;
617			n_contrib[pix_id] = last_contributor;
618			for (int ch = 0; ch < CHANNELS; ch++)
619				out_color[ch * H * W + pix_id] = C[ch] + T * bg_color[ch];
620			for (int ch = 0; ch < 2; ch++)
621				out_flow[ch * H * W + pix_id] = Flow[ch];
622			out_depth[pix_id] = D;
623		}
624	}
625	
626	void FORWARD::render(
627		const dim3 grid, dim3 block,
628		const uint2* ranges,
629		const uint32_t* point_list,
630		int W, int H,
631		const float2* means2D,
632		const float* colors,
633		const float* flows,
634		const float* depths,
635		const float4* conic_opacity,
636		float* final_T,
637		uint32_t* n_contrib,
638		const float* bg_color,
639		float* out_color,
640		float* out_flow,
641		float* out_depth)
642	{
643		renderCUDA<NUM_CHANNELS> << <grid, block >> > (
644			ranges,
645			point_list,
646			W, H,
647			means2D,
648			colors,
649			flows,
650			depths,
651			conic_opacity,
652			final_T,
653			n_contrib,
654			bg_color,
655			out_color,
656			out_flow,
657			out_depth);
658	}
659	
660	void FORWARD::preprocess(int P, int D, int D_t, int M,
661		const float* means3D,
662		float* out_means3D,
663		const float* ts,
664		const glm::vec3* scales,
665		const float* scales_t,
666		const float scale_modifier,
667		const glm::vec4* rotations,
668		const glm::vec4* rotations_r,
669		const float* opacities,
670		const float* shs,
671		bool* clamped,
672		const float* cov3D_precomp,
673		const float* colors_precomp,
674		const float* viewmatrix,
675		const float* projmatrix,
676		const glm::vec3* cam_pos,
677		const float timestamp,
678		const float time_duration,
679		const bool rot_4d, const int gaussian_dim, const bool force_sh_3d,
680		const int W, int H,
681		const float focal_x, float focal_y,
682		const float tan_fovx, float tan_fovy,
683		int* radii,
684		float2* means2D,
685		float* depths,
686		float* cov3Ds,
687		float* rgb,
688		float4* conic_opacity,
689		const dim3 grid,
690		uint32_t* tiles_touched,
691		bool prefiltered)
692	{
693		preprocessCUDA<NUM_CHANNELS> << <(P + 255) / 256, 256 >> > (
694			P, D, D_t, M,
695			means3D,
696			out_means3D,
697			ts,
698			scales,
699			scales_t,
700			scale_modifier,
701			rotations,
702			rotations_r,
703			opacities,
704			shs,
705			clamped,
706			cov3D_precomp,
707			colors_precomp,
708			viewmatrix,
709			projmatrix,
710			cam_pos,
711			timestamp,
712			time_duration,
713			rot_4d, gaussian_dim, force_sh_3d,
714			W, H,
715			tan_fovx, tan_fovy,
716			focal_x, focal_y,
717			radii,
718			means2D,
719			depths,
720			cov3Ds,
721			rgb,
