141	
142	// Backward pass for conversion of spherical harmonics to RGB for
143	// each Gaussian.
144	__device__ void computeColorFromSH_4D(int idx, int deg, int deg_t, int max_coeffs, const glm::vec3* means, glm::vec3 campos,
145	            const float* shs, const bool* clamped, const float* ts, const float timestamp, const float time_duration,
146	            const glm::vec3* dL_dcolor, glm::vec3* dL_dmeans, glm::vec3* dL_dshs, float* dL_dts)
147	{
148		// Compute intermediate values, as it is done during forward
149		const float dir_t = ts[idx] - timestamp;
150		glm::vec3 pos = means[idx];
151		glm::vec3 dir_orig = pos - campos;
152		glm::vec3 dir = dir_orig / glm::length(dir_orig);
153	
154		glm::vec3* sh = ((glm::vec3*)shs) + idx * max_coeffs;
