160		dL_dRGB.y *= clamped[3 * idx + 1] ? 0 : 1;
161		dL_dRGB.z *= clamped[3 * idx + 2] ? 0 : 1;
162	
163		glm::vec3 dRGBdx(0, 0, 0);
164		glm::vec3 dRGBdy(0, 0, 0);
