171		// No tricks here, just high school-level calculus.
172		float l0m0 = SH_C0;
173	
174		float dRGBdsh0 = l0m0;
175		dL_dsh[0] = dRGBdsh0 * dL_dRGB;
176	
177		if (deg > 0){
