179	        float y = dir.y;
180	        float z = dir.z;
181	
182	        float l1m1 = -1 * SH_C1 * y;
183			float l1m0 = SH_C1 * z;
184			float l1p1 = -1 * SH_C1 * x;
185	
186			float dl1m1_dy = -1 * SH_C1;
187			float dl1m0_dz = SH_C1;
188			float dl1p1_dx = -1 * SH_C1;
189	
190			dL_dsh[1] = l0m0 * dL_dRGB;
191			dL_dsh[2] = l1m0 * dL_dRGB;
192			dL_dsh[3] = l1p1 * dL_dRGB;
193	
194			dRGBdx = dl1p1_dx * sh[3];
195			dRGBdy = dl1m1_dy * sh[1];
196			dRGBdz = dl1m0_dz * sh[2];
197	
198			if (deg > 1){
199				float xx = x * x, yy = y * y, zz = z * z;
200				float xy = x * y, yz = y * z, xz = x * z;
201	
202				float l2m2 = SH_C2[0] * xy;
203	            float l2m1 = SH_C2[1] * yz;
204	            float l2m0 = SH_C2[2] * (2.0 * zz - xx - yy);
205	            float l2p1 = SH_C2[3] * xz;
206	            float l2p2 = SH_C2[4] * (xx - yy);
207	
208	            float dl2m2_dx = SH_C2[0] * y;
209	            float dl2m2_dy = SH_C2[0] * x;
210	            float dl2m1_dy = SH_C2[1] * z;
211	            float dl2m1_dz = SH_C2[1] * y;
212	            float dl2m0_dx = -2 * SH_C2[2] * x;
213	            float dl2m0_dy = -2 * SH_C2[2] * y;
214	            float dl2m0_dz = 4 * SH_C2[2] * z;
215	            float dl2p1_dx = SH_C2[3] * z;
216	            float dl2p1_dz = SH_C2[3] * x;
217	            float dl2p2_dx = 2 * SH_C2[4] * x;
218	            float dl2p2_dy = -2 * SH_C2[4] * y;
219	
220				dL_dsh[4] = l2m2 * dL_dRGB;
221				dL_dsh[5] = l2m1 * dL_dRGB;
222				dL_dsh[6] = l2m0 * dL_dRGB;
223				dL_dsh[7] = l2p1 * dL_dRGB;
224				dL_dsh[8] = l2p2 * dL_dRGB;
225	
226				dRGBdx += (
227					dl2m2_dx * sh[4] + dl2m0_dx * sh[6] + dl2p1_dx * sh[7] + dl2p2_dx * sh[8]
228				);
229				dRGBdy += (
230					dl2m2_dy * sh[4] + dl2m1_dy * sh[5] + dl2m0_dy * sh[6] + dl2p2_dy * sh[8]
231				);
232				dRGBdz += (
233					dl2m1_dz * sh[5] + dl2m0_dz * sh[6] + dl2p1_dz * sh[7]
234				);
235	
236				if (deg > 2){
237					float l3m3 = SH_C3[0] * y * (3 * xx - yy);
238	                float l3m2 = SH_C3[1] * xy * z;
239	                float l3m1 = SH_C3[2] * y * (4 * zz - xx - yy);
240	                float l3m0 = SH_C3[3] * z * (2 * zz - 3 * xx - 3 * yy);
241	                float l3p1 = SH_C3[4] * x * (4 * zz - xx - yy);
242	                float l3p2 = SH_C3[5] * z * (xx - yy);
243	                float l3p3 = SH_C3[6] * x * (xx - 3 * yy);
244	
245	                float dl3m3_dx = SH_C3[0] * y * 6 * x;
246	                float dl3m3_dy = SH_C3[0] * (3 * xx - 3 * yy);
247	                float dl3m2_dx = SH_C3[1] * yz;
248	                float dl3m2_dy = SH_C3[1] * xz;
249	                float dl3m2_dz = SH_C3[1] * xy;
250	                float dl3m1_dx = -SH_C3[2] * y * 2 * x;
251	                float dl3m1_dy = SH_C3[2] * (4 * zz - xx - 3 * yy);
252	                float dl3m1_dz = SH_C3[2] * y * 8 * z;
253	                float dl3m0_dx = -SH_C3[3] * z * 6 * x;
254	                float dl3m0_dy = -SH_C3[3] * z * 6 * y;
255	                float dl3m0_dz = SH_C3[3] * (6 * zz - 3 * xx - 3 * yy);
256	                float dl3p1_dx = SH_C3[4] * (4 * zz - 3 * xx - yy);
257	                float dl3p1_dy = -SH_C3[4] * x * 2 * y;
258	                float dl3p1_dz = SH_C3[4] * x * 8 * z;
259	                float dl3p2_dx = SH_C3[5] * z * 2 * x;
260	                float dl3p2_dy = -SH_C3[5] * z * 2 * y;
261	                float dl3p2_dz = SH_C3[5] * (xx - yy);
262	                float dl3p3_dx = SH_C3[6] * (3 * xx - 3 * yy);
263	                float dl3p3_dy = -SH_C3[6] * x * 6 * y;
264	
265					dL_dsh[9] = l3m3 * dL_dRGB;
266					dL_dsh[10] = l3m2 * dL_dRGB;
267					dL_dsh[11] = l3m1 * dL_dRGB;
268					dL_dsh[12] = l3m0 * dL_dRGB;
269					dL_dsh[13] = l3p1 * dL_dRGB;
270					dL_dsh[14] = l3p2 * dL_dRGB;
271					dL_dsh[15] = l3p3 * dL_dRGB;
272	
273					dRGBdx += (
274						dl3m3_dx * sh[9] +
275						dl3m2_dx * sh[10] +
276						dl3m1_dx * sh[11] +
277						dl3m0_dx * sh[12] +
278						dl3p1_dx * sh[13] +
279						dl3p2_dx * sh[14] +
280						dl3p3_dx * sh[15]
281	                );
282	
283					dRGBdy += (
284	                    dl3m3_dy * sh[9] +
285						dl3m2_dy * sh[10] +
286						dl3m1_dy * sh[11] +
287						dl3m0_dy * sh[12] +
288						dl3p1_dy * sh[13] +
289						dl3p2_dy * sh[14] +
290						dl3p3_dy * sh[15]
291	                );
292	
293					dRGBdz += (
294						dl3m2_dz * sh[10] +
295						dl3m1_dz * sh[11] +
296						dl3m0_dz * sh[12] +
297						dl3p1_dz * sh[13] +
298						dl3p2_dz * sh[14]
299	                );
300	
301					if (deg_t > 0){
302						float t1 = cos(2 * MY_PI * dir_t / time_duration);
303						float dt1_dt = sin(2 * MY_PI * dir_t / time_duration) * 2 * MY_PI / time_duration;
304	
305						dL_dsh[16] = t1 * l0m0 * dL_dRGB;
306						dL_dsh[17] = t1 * l1m1 * dL_dRGB;
307						dL_dsh[18] = t1 * l1m0 * dL_dRGB;
308						dL_dsh[19] = t1 * l1p1 * dL_dRGB;
309						dL_dsh[20] = t1 * l2m2 * dL_dRGB;
310						dL_dsh[21] = t1 * l2m1 * dL_dRGB;
311						dL_dsh[22] = t1 * l2m0 * dL_dRGB;
312						dL_dsh[23] = t1 * l2p1 * dL_dRGB;
313						dL_dsh[24] = t1 * l2p2 * dL_dRGB;
314						dL_dsh[25] = t1 * l3m3 * dL_dRGB;
315						dL_dsh[26] = t1 * l3m2 * dL_dRGB;
316						dL_dsh[27] = t1 * l3m1 * dL_dRGB;
317						dL_dsh[28] = t1 * l3m0 * dL_dRGB;
318						dL_dsh[29] = t1 * l3p1 * dL_dRGB;
319						dL_dsh[30] = t1 * l3p2 * dL_dRGB;
320						dL_dsh[31] = t1 * l3p3 * dL_dRGB;
321	
322						dRGBdt = dt1_dt * (
323							l0m0 * sh[16] +
324							l1m1 * sh[17] +
325							l1m0 * sh[18] +
326							l1p1 * sh[19] + 
327							l2m2 * sh[20] +
328							l2m1 * sh[21] +
329							l2m0 * sh[22] +
330							l2p1 * sh[23] +
331							l2p2 * sh[24] + 
332							l3m3 * sh[25] +
333							l3m2 * sh[26] +
334							l3m1 * sh[27] +
335							l3m0 * sh[28] +
336							l3p1 * sh[29] +
337							l3p2 * sh[30] +
338							l3p3 * sh[31]);
339	
340						dRGBdx += t1 * (
341							dl1p1_dx * sh[19] + 
342							dl2m2_dx * sh[20] + 
343							dl2m0_dx * sh[22] + 
344							dl2p1_dx * sh[23] + 
345							dl2p2_dx * sh[24] + 
346							dl3m3_dx * sh[25] +
347							dl3m2_dx * sh[26] +
348							dl3m1_dx * sh[27] +
349							dl3m0_dx * sh[28] +
350							dl3p1_dx * sh[29] +
351							dl3p2_dx * sh[30] +
352							dl3p3_dx * sh[31]
353						);
354	
355						dRGBdy += t1 * (
356							dl1m1_dy * sh[17] +
357							dl2m2_dy * sh[20] + 
358							dl2m1_dy * sh[21] + 
359							dl2m0_dy * sh[22] + 
360							dl2p2_dy * sh[24] + 
361							dl3m3_dy * sh[25] +
362							dl3m2_dy * sh[26] +
363							dl3m1_dy * sh[27] +
364							dl3m0_dy * sh[28] +
365							dl3p1_dy * sh[29] +
366							dl3p2_dy * sh[30] +
367							dl3p3_dy * sh[31]
368						);
369	
370						dRGBdz += t1 * (
371							dl1m0_dz * sh[18] +
372							dl2m1_dz * sh[21] + 
373							dl2m0_dz * sh[22] + 
374							dl2p1_dz * sh[23] +
375							dl3m2_dz * sh[26] +
376							dl3m1_dz * sh[27] +
377							dl3m0_dz * sh[28] +
378							dl3p1_dz * sh[29] +
379							dl3p2_dz * sh[30]
380						);
381	
382						if (deg_t > 1){
383							float t2 = cos(2 * MY_PI * dir_t * 2 / time_duration);
384							float dt2_dt = sin(2 * MY_PI * dir_t * 2 / time_duration) * 2 * MY_PI * 2 / time_duration;
385	
386							dL_dsh[32] = t2 * l0m0 * dL_dRGB;
387							dL_dsh[33] = t2 * l1m1 * dL_dRGB;
388							dL_dsh[34] = t2 * l1m0 * dL_dRGB;
389							dL_dsh[35] = t2 * l1p1 * dL_dRGB;
390							dL_dsh[36] = t2 * l2m2 * dL_dRGB;
391							dL_dsh[37] = t2 * l2m1 * dL_dRGB;
392							dL_dsh[38] = t2 * l2m0 * dL_dRGB;
393							dL_dsh[39] = t2 * l2p1 * dL_dRGB;
394							dL_dsh[40] = t2 * l2p2 * dL_dRGB;
395							dL_dsh[41] = t2 * l3m3 * dL_dRGB;
396							dL_dsh[42] = t2 * l3m2 * dL_dRGB;
397							dL_dsh[43] = t2 * l3m1 * dL_dRGB;
398							dL_dsh[44] = t2 * l3m0 * dL_dRGB;
399							dL_dsh[45] = t2 * l3p1 * dL_dRGB;
400							dL_dsh[46] = t2 * l3p2 * dL_dRGB;

