483	// Backward version of INVERSE 2D covariance matrix computation
484	// (due to length launched as separate kernel before other 
485	// backward steps contained in preprocess)
486	__global__ void computeCov2DCUDA(int P,
487		const float3* means,
488		const int* radii,
489		const float* cov3Ds,
490		const float h_x, float h_y,
491		const float tan_fovx, float tan_fovy,
492		const float* view_matrix,
493		const float* dL_dconics,
494		const float3* dL_dmean2D,
495		float3* dL_dmeans,
496		float* dL_dcov)
497	{
498		auto idx = cg::this_grid().thread_rank();
499		if (idx >= P || !(radii[idx] > 0))
500			return;
501	
502		// Reading location of 3D covariance for this Gaussian
503		const float* cov3D = cov3Ds + 6 * idx;
504	
505		// Fetch gradients, recompute 2D covariance and relevant 
506		// intermediate forward results needed in the backward.
507		float3 mean = means[idx];
508		float3 dL_dconic = { dL_dconics[4 * idx], dL_dconics[4 * idx + 1], dL_dconics[4 * idx + 3] };
509		float3 t = transformPoint4x3(mean, view_matrix);
510		
511		const float limx = 1.3f * tan_fovx;
512		const float limy = 1.3f * tan_fovy;
513		const float txtz = t.x / t.z;
514		const float tytz = t.y / t.z;
515		t.x = min(limx, max(-limx, txtz)) * t.z;
516		t.y = min(limy, max(-limy, tytz)) * t.z;
517		
518		const float x_grad_mul = txtz < -limx || txtz > limx ? 0 : 1;
519		const float y_grad_mul = tytz < -limy || tytz > limy ? 0 : 1;
520	
521		glm::mat3 J = glm::mat3(h_x / t.z, 0.0f, -(h_x * t.x) / (t.z * t.z),
522			0.0f, h_y / t.z, -(h_y * t.y) / (t.z * t.z),
523			0, 0, 0);
524	
525		glm::mat3 W = glm::mat3(
526			view_matrix[0], view_matrix[4], view_matrix[8],
527			view_matrix[1], view_matrix[5], view_matrix[9],
528			view_matrix[2], view_matrix[6], view_matrix[10]);
529	
530		glm::mat3 Vrk = glm::mat3(
531			cov3D[0], cov3D[1], cov3D[2],
532			cov3D[1], cov3D[3], cov3D[4],
533			cov3D[2], cov3D[4], cov3D[5]);
534	
535		glm::mat3 T = W * J;
536	
537		glm::mat3 cov2D = glm::transpose(T) * glm::transpose(Vrk) * T;
538	
539		// Use helper variables for 2D covariance entries. More compact.
540		float a = cov2D[0][0] += 0.3f;
541		float b = cov2D[0][1];
542		float c = cov2D[1][1] += 0.3f;
543	
544		float denom = a * c - b * b;
545		float dL_da = 0, dL_db = 0, dL_dc = 0;
546		float denom2inv = 1.0f / ((denom * denom) + 0.0000001f);
547	
548		if (denom2inv != 0)
549		{
550			// Gradients of loss w.r.t. entries of 2D covariance matrix,
551			// given gradients of loss w.r.t. conic matrix (inverse covariance matrix).
552			// e.g., dL / da = dL / d_conic_a * d_conic_a / d_a
553			dL_da = denom2inv * (-c * c * dL_dconic.x + 2 * b * c * dL_dconic.y + (denom - a * c) * dL_dconic.z);
554			dL_dc = denom2inv * (-a * a * dL_dconic.z + 2 * a * b * dL_dconic.y + (denom - a * c) * dL_dconic.x);
555			dL_db = denom2inv * 2 * (b * c * dL_dconic.x - (denom + 2 * b * b) * dL_dconic.y + a * b * dL_dconic.z);
556	
557			// Gradients of loss L w.r.t. each 3D covariance matrix (Vrk) entry, 
558			// given gradients w.r.t. 2D covariance matrix (diagonal).
559			// cov2D = transpose(T) * transpose(Vrk) * T;
560			dL_dcov[6 * idx + 0] = (T[0][0] * T[0][0] * dL_da + T[0][0] * T[1][0] * dL_db + T[1][0] * T[1][0] * dL_dc);
561			dL_dcov[6 * idx + 3] = (T[0][1] * T[0][1] * dL_da + T[0][1] * T[1][1] * dL_db + T[1][1] * T[1][1] * dL_dc);
562			dL_dcov[6 * idx + 5] = (T[0][2] * T[0][2] * dL_da + T[0][2] * T[1][2] * dL_db + T[1][2] * T[1][2] * dL_dc);
563	
564			// Gradients of loss L w.r.t. each 3D covariance matrix (Vrk) entry, 
565			// given gradients w.r.t. 2D covariance matrix (off-diagonal).
566			// Off-diagonal elements appear twice --> double the gradient.
567			// cov2D = transpose(T) * transpose(Vrk) * T;
568			dL_dcov[6 * idx + 1] = 2 * T[0][0] * T[0][1] * dL_da + (T[0][0] * T[1][1] + T[0][1] * T[1][0]) * dL_db + 2 * T[1][0] * T[1][1] * dL_dc;
569			dL_dcov[6 * idx + 2] = 2 * T[0][0] * T[0][2] * dL_da + (T[0][0] * T[1][2] + T[0][2] * T[1][0]) * dL_db + 2 * T[1][0] * T[1][2] * dL_dc;
570			dL_dcov[6 * idx + 4] = 2 * T[0][2] * T[0][1] * dL_da + (T[0][1] * T[1][2] + T[0][2] * T[1][1]) * dL_db + 2 * T[1][1] * T[1][2] * dL_dc;
571		}
572		else
573		{
574			for (int i = 0; i < 6; i++)
575				dL_dcov[6 * idx + i] = 0;
576		}
577	
578		// Gradients of loss w.r.t. upper 2x3 portion of intermediate matrix T
579		// cov2D = transpose(T) * transpose(Vrk) * T;
580		float dL_dT00 = 2 * (T[0][0] * Vrk[0][0] + T[0][1] * Vrk[0][1] + T[0][2] * Vrk[0][2]) * dL_da +
581			(T[1][0] * Vrk[0][0] + T[1][1] * Vrk[0][1] + T[1][2] * Vrk[0][2]) * dL_db;
582		float dL_dT01 = 2 * (T[0][0] * Vrk[1][0] + T[0][1] * Vrk[1][1] + T[0][2] * Vrk[1][2]) * dL_da +
583			(T[1][0] * Vrk[1][0] + T[1][1] * Vrk[1][1] + T[1][2] * Vrk[1][2]) * dL_db;
584		float dL_dT02 = 2 * (T[0][0] * Vrk[2][0] + T[0][1] * Vrk[2][1] + T[0][2] * Vrk[2][2]) * dL_da +
585			(T[1][0] * Vrk[2][0] + T[1][1] * Vrk[2][1] + T[1][2] * Vrk[2][2]) * dL_db;
586		float dL_dT10 = 2 * (T[1][0] * Vrk[0][0] + T[1][1] * Vrk[0][1] + T[1][2] * Vrk[0][2]) * dL_dc +
587			(T[0][0] * Vrk[0][0] + T[0][1] * Vrk[0][1] + T[0][2] * Vrk[0][2]) * dL_db;
588		float dL_dT11 = 2 * (T[1][0] * Vrk[1][0] + T[1][1] * Vrk[1][1] + T[1][2] * Vrk[1][2]) * dL_dc +
589			(T[0][0] * Vrk[1][0] + T[0][1] * Vrk[1][1] + T[0][2] * Vrk[1][2]) * dL_db;
590		float dL_dT12 = 2 * (T[1][0] * Vrk[2][0] + T[1][1] * Vrk[2][1] + T[1][2] * Vrk[2][2]) * dL_dc +
591			(T[0][0] * Vrk[2][0] + T[0][1] * Vrk[2][1] + T[0][2] * Vrk[2][2]) * dL_db;
592	
593		// Gradients of loss w.r.t. upper 3x2 non-zero entries of Jacobian matrix
594		// T = W * J
595		float dL_dJ00 = W[0][0] * dL_dT00 + W[0][1] * dL_dT01 + W[0][2] * dL_dT02;
596		float dL_dJ02 = W[2][0] * dL_dT00 + W[2][1] * dL_dT01 + W[2][2] * dL_dT02;
597		float dL_dJ11 = W[1][0] * dL_dT10 + W[1][1] * dL_dT11 + W[1][2] * dL_dT12;
598		float dL_dJ12 = W[2][0] * dL_dT10 + W[2][1] * dL_dT11 + W[2][2] * dL_dT12;
599	
600		float tz = 1.f / t.z;
601		float tz2 = tz * tz;
602		float tz3 = tz2 * tz;
603	
604		// Gradients of loss w.r.t. transformed Gaussian mean t
605		float dL_dtx = x_grad_mul * -h_x * tz2 * dL_dJ02;
606		float dL_dty = y_grad_mul * -h_y * tz2 * dL_dJ12;
607		float dL_dtz = -h_x * tz2 * dL_dJ00 - h_y * tz2 * dL_dJ11 + (2 * h_x * t.x) * tz3 * dL_dJ02 + (2 * h_y * t.y) * tz3 * dL_dJ12;
608	
609		// Account for transformation of mean to t
610		// t = transformPoint4x3(mean, view_matrix);
611		float3 dL_dmean = transformVec4x3Transpose({ dL_dtx, dL_dty, dL_dtz+dL_dmean2D[idx].z }, view_matrix);
612	
613		// Gradients of loss w.r.t. Gaussian means, but only the portion 
614		// that is caused because the mean affects the covariance matrix.
615		// Additional mean gradient is accumulated in BACKWARD::preprocess.
616		dL_dmeans[idx] = dL_dmean;
617	}
