619	// Backward pass for the conversion of scale and rotation to a 
620	// 3D covariance matrix for each Gaussian. 
621	__device__ void computeCov3D(int idx, const glm::vec3 scale, float mod, const glm::vec4 rot, const float* dL_dcov3Ds, glm::vec3* dL_dscales, glm::vec4* dL_drots)
622	{
623		// Recompute (intermediate) results for the 3D covariance computation.
624		glm::vec4 q = rot;// / glm::length(rot);
625		float r = q.x;
626		float x = q.y;
627		float y = q.z;
628		float z = q.w;
629	
630		glm::mat3 R = glm::mat3(
631			1.f - 2.f * (y * y + z * z), 2.f * (x * y - r * z), 2.f * (x * z + r * y),
632			2.f * (x * y + r * z), 1.f - 2.f * (x * x + z * z), 2.f * (y * z - r * x),
633			2.f * (x * z - r * y), 2.f * (y * z + r * x), 1.f - 2.f * (x * x + y * y)
634		);
635	
636		glm::mat3 S = glm::mat3(1.0f);
637	
638		glm::vec3 s = mod * scale;
639		S[0][0] = s.x;
640		S[1][1] = s.y;
641		S[2][2] = s.z;
642	
643		glm::mat3 M = S * R;
644	
645		const float* dL_dcov3D = dL_dcov3Ds + 6 * idx;
646	
647		// glm::vec3 dunc(dL_dcov3D[0], dL_dcov3D[3], dL_dcov3D[5]);
648		// glm::vec3 ounc = 0.5f * glm::vec3(dL_dcov3D[1], dL_dcov3D[2], dL_dcov3D[4]);
649	
650		// Convert per-element covariance loss gradients to matrix form
651		glm::mat3 dL_dSigma = glm::mat3(
652			dL_dcov3D[0], 0.5f * dL_dcov3D[1], 0.5f * dL_dcov3D[2],
653			0.5f * dL_dcov3D[1], dL_dcov3D[3], 0.5f * dL_dcov3D[4],
654			0.5f * dL_dcov3D[2], 0.5f * dL_dcov3D[4], dL_dcov3D[5]
655		);
656	
657		// Compute loss gradient w.r.t. matrix M
658		// dSigma_dM = 2 * M
659		glm::mat3 dL_dM = 2.0f * M * dL_dSigma;
660	
661		glm::mat3 Rt = glm::transpose(R);
662		glm::mat3 dL_dMt = glm::transpose(dL_dM);
663	
664		// Gradients of loss w.r.t. scale
665		glm::vec3* dL_dscale = dL_dscales + idx;
